/* ================= CONFIGURACIÓN ================= */
const CONFIG = {
  // Ya no necesitamos CLIENT_ID de Google
  // Único correo que puede entrar (puedes cambiarlo si deseas)
  CORREOS_PERMITIDOS: ["nuestrahistoriaenpixeles@gmail.com"],
  // Clave en hash SHA-256 (corresponde a: 10/46january)
  CLAVE_HASH: "2afab3ac326d7664a787b9650c816f30cbb6f62a13ef76111a1c1faf0387abdf",
  // Inicio de la relación
  INICIO: new Date(2026, 0, 11, 22, 46, 0)
};

const $ = (s, c = document) => c.querySelector(s), $$ = (s, c = document) => [...c.querySelectorAll(s)];
const sha = async t => [...new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(t)))].map(b => b.toString(16).padStart(2, "0")).join("");
window.generarHash = async t => { const h = await sha(t); console.log(h); return h; };
const aviso = t => $("#error").textContent = t;

/* ---------- Acceso directo por Correo y Clave ---------- */
function pedirClave(correo) {
  const ok = CONFIG.CORREOS_PERMITIDOS.map(c => c.toLowerCase());
  if (ok.length && !ok.includes(correo.toLowerCase())) return aviso("Esta cuenta no tiene acceso.");
  aviso(""); $("#paso1").hidden = true; $("#formClave").hidden = false;
  $("#quien").textContent = correo; $("#clave").focus();
}

// Al cargar la página, saltamos la validación de Google y habilitamos el formulario manual de inmediato
addEventListener("load", () => {
  // Mostramos directamente el campo de correo manual sin importar si es local o público
  $("#manual").hidden = false; 
  
  // Ocultamos o removemos cualquier elemento visual del botón de Google si existiera en el HTML
  const contenedorGoogle = $("#btnGoogle");
  if (contenedorGoogle) contenedorGoogle.style.display = "none";
});

$("#manual").onsubmit = e => { 
  e.preventDefault(); 
  pedirClave($("#correoManual").value); 
};

$("#formClave").onsubmit = async e => {
  e.preventDefault();
  if (await sha($("#clave").value.trim()) === CONFIG.CLAVE_HASH) {
    $("#login").hidden = true; $("#app").hidden = false; mostrar("inicio");
  } else { aviso("Clave incorrecta, inténtalo de nuevo."); $("#clave").value = ""; }
};

$("#salir").onclick = () => location.reload();

/* ---------- Reloj en tiempo real ---------- */
const cajas = $$("#reloj b"), I = CONFIG.INICIO;
function tic() {
  const n = new Date();
  let m = (n.getFullYear() - I.getFullYear()) * 12 + n.getMonth() - I.getMonth();
  let b = new Date(I); b.setMonth(I.getMonth() + m);
  if (b > n) { m--; b = new Date(I); b.setMonth(I.getMonth() + m); }
  const s = Math.floor((n - b) / 1000);
  [m, Math.floor(s / 86400), Math.floor(s % 86400 / 3600), Math.floor(s % 3600 / 60), s % 60]
    .forEach((v, i) => cajas[i].textContent = String(v).padStart(2, "0"));
}
tic(); setInterval(tic, 1000);

/* ---------- Visor: galería (fotos y videos en orden) y PDF ---------- */
const visor = $("#visor"), cont = $("#visorCont"), dl = $("#visorDl");
let items = [], pos = 0, z = 1, medio = null; // z = zoom (1 = archivo completo)
function abrirVisor(url, titulo, flechas) {
  $$(".video-aviso").forEach(x => x.remove());
  dl.href = abrir.href = url;
  const nom = document.createElement("b"), sub = document.createElement("small");   // nombre del archivo + título
  nom.textContent = nombreDe(url); sub.textContent = titulo; $("#visorTit").replaceChildren(nom, sub);
  $("#ant").hidden = $("#sig").hidden = !flechas;
  visor.hidden = false; document.body.style.overflow = "hidden";
}
function verItem(i) {
  pos = (i + items.length) % items.length;
  const f = items[pos], esVideo = f.dataset.tipo === "video";
  const url = f.querySelector(esVideo ? "video" : "img").src.split("#")[0];
  const c = f.querySelector("figcaption"), t = c ? [...c.childNodes].filter(n => n.nodeType === 3).map(n => n.textContent).join("").trim() : "";   // título sin el nombre del archivo
  const el = esVideo ? document.createElement("video") : new Image();
  el.src = url;
  if (esVideo) Object.assign(el, { controls: true, autoplay: true, playsInline: true }); else Object.assign(el, { alt: t, draggable: false });
  medio = el; z = obj = 1; cancelAnimationFrame(anim); cont.style.touchAction = esVideo ? "pan-x pan-y" : "none"; el.onload = el.onloadedmetadata = () => { ajustar(); if (esVideo && !el.videoWidth) panelVideo(); };
  cont.innerHTML = ""; cont.append(el);
  abrirVisor(url, `${t} (${pos + 1} de ${items.length})`, items.length > 1);
}
/* ---------- Lector de documentos PDF (páginas dentro de la web, con zoom) ---------- */
function cargarPdfJs() {
  const ya = window.pdfjsLib || window["pdfjs-dist/build/pdf"];
  if (ya) return Promise.resolve(ya);
  return new Promise((ok, mal) => {
    const s = document.createElement("script");
    s.src = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js";
    s.onload = () => {
      const lib = window.pdfjsLib || window["pdfjs-dist/build/pdf"];
      lib.GlobalWorkerOptions.workerSrc = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js"; ok(lib);
    };
    s.onerror = () => mal(new Error("pdfjs"));
    document.head.append(s);
  });
}
async function verPdf(url, titulo) {
  if (location.protocol === "file:") return verPdfNativo(url, titulo);   // con doble clic el lector no puede leer el archivo
  const cargando = document.createElement("div");
  cargando.className = "pdf-aviso"; cargando.textContent = "Abriendo documento…";
  medio = cargando; z = obj = 1; cancelAnimationFrame(anim); cont.style.touchAction = "pan-x pan-y";
  cont.innerHTML = ""; cont.append(cargando); abrirVisor(url, titulo, false);
  try {
    const lib = await cargarPdfJs();
    const pdf = await lib.getDocument(new URL(url, location.href).href).promise;
    if (medio !== cargando) return;
    const p1 = await pdf.getPage(1), v1 = p1.getViewport({ scale: 1 });
    const ancho = Math.min(cont.clientWidth * .97, 1000), dpr = Math.min(window.devicePixelRatio || 1, 2);
    const pintar = async c => {   // cada hoja se dibuja cuando te acercas a ella
      const p = await pdf.getPage(+c.dataset.n), v = p.getViewport({ scale: Math.min(2000, ancho * 1.5 * dpr) / p.getViewport({ scale: 1 }).width });
      c.width = v.width; c.height = v.height; c.style.aspectRatio = v.width + " / " + v.height;
      await p.render({ canvasContext: c.getContext("2d"), viewport: v }).promise;
    };
    const ver = new IntersectionObserver(es => es.forEach(x => { if (x.isIntersecting) { ver.unobserve(x.target); pintar(x.target); } }), { root: cont, rootMargin: "900px 0px" });
    const hojas = document.createElement("div"); hojas.className = "pdf-hojas";
    for (let n = 1; n <= pdf.numPages; n++) {
      const c = document.createElement("canvas"); c.dataset.n = n; c.style.aspectRatio = v1.width + " / " + v1.height;
      hojas.append(c); ver.observe(c);
    }
    medio = hojas; cont.innerHTML = ""; cont.append(hojas);
    abrirVisor(url, `${titulo} · ${pdf.numPages} página${pdf.numPages > 1 ? "s" : ""}`, false);
    ajustar(); cont.tabIndex = -1; cont.focus({ preventScroll: true });
  } catch { if (medio === cargando) verPdfNativo(url, titulo); }
}
function verPdfNativo(url, titulo) {
  const ob = document.createElement("object"), aviso = document.createElement("div"), l = document.createElement("a");
  ob.data = url; ob.type = "application/pdf";
  aviso.className = "pdf-aviso"; aviso.innerHTML = "<p>No se pudo mostrar el PDF aquí (tu navegador no lo permite o no se encuentra el archivo).</p>";
  Object.assign(l, { href: url, target: "_blank", rel: "noopener", textContent: "Abrir en otra pestaña", className: "dl" });
  aviso.append(l); ob.append(aviso);
  medio = ob; z = obj = 1; cancelAnimationFrame(anim); cont.style.touchAction = "pan-x pan-y";
  cont.innerHTML = ""; cont.append(ob); abrirVisor(url, titulo, false); ajustar();
}
function cerrar() {
  if (document.fullscreenElement) document.exitFullscreen();
  medio = null; $$(".video-aviso").forEach(x => x.remove()); visor.hidden = true; cont.innerHTML = ""; document.body.style.overflow = "";
}
/* ---------- Zoom: solo el contenido (50% a 150%), fluido y exacto ---------- */
let obj = 1, anim = 0;
function ajustar() {
  if (!medio) return;
  const p = Math.round(z * 100);
  $("#zPct").textContent = p + "%"; $("#zRango").value = p;
  const w = cont.clientWidth, h = cont.clientHeight;
  if (medio.tagName === "OBJECT") { medio.style.width = w * z + "px"; medio.style.height = h + "px"; return; }
  if (medio.classList.contains("pdf-hojas")) { medio.style.width = Math.min(w * .97, 1000) * z + "px"; return; }
  const nw = medio.naturalWidth || medio.videoWidth, nh = medio.naturalHeight || medio.videoHeight;
  if (!nw) return;
  const k = Math.min(w / nw, h / nh) * .97 * z;   // 100% = archivo completo, centrado y ajustado a la pantalla
  medio.style.width = nw * k + "px"; medio.style.height = nh * k + "px";
}
function poner(v) {   // aplica el zoom v conservando el centro de lo que se está viendo
  const rx = (cont.scrollLeft + cont.clientWidth / 2) / (cont.scrollWidth || 1), ry = (cont.scrollTop + cont.clientHeight / 2) / (cont.scrollHeight || 1);
  z = v; ajustar();
  cont.scrollLeft = rx * cont.scrollWidth - cont.clientWidth / 2; cont.scrollTop = ry * cont.scrollHeight - cont.clientHeight / 2;
}
function zoom(n, suave = true) {
  if (!medio) return;
  obj = Math.min(1.5, Math.max(.5, n));
  cancelAnimationFrame(anim);
  if (!suave) { anim = 0; return poner(obj); }
  const ini = z, t0 = performance.now();
  (function paso(t) {
    const p = Math.min(1, (t - t0) / 170);
    poner(ini + (obj - ini) * (1 - (1 - p) ** 3));
    anim = p < 1 ? requestAnimationFrame(paso) : 0;
  })(t0);
}
const escalon = d => { const a = (anim ? obj : z) * 10; zoom((d > 0 ? Math.floor(a + 1e-6) + 1 : Math.ceil(a - 1e-6) - 1) / 10); };
const rango = document.createElement("input");
Object.assign(rango, { type: "range", min: 50, max: 150, step: 1, value: 100, id: "zRango" });
rango.setAttribute("aria-label", "Zoom");
$("#zMenos").after(rango); $("#zMas").after($("#zPct"));   // orden: − barra + 100%
rango.oninput = () => zoom(rango.value / 100, false);
$("#zMas").onclick = () => escalon(1);
$("#zMenos").onclick = () => escalon(-1);
$("#zPct").onclick = () => zoom(1);
visor.addEventListener("wheel", e => {   // rueda / pellizco del trackpad: solo la foto o el video, nunca toda la página
  if (visor.hidden) return;
  const t = medio?.tagName;
  if (e.ctrlKey || (t === "IMG" && cont.contains(e.target))) {
    e.preventDefault();
    if (t === "IMG" || t === "VIDEO" || medio?.classList.contains("pdf-hojas")) zoom(z * Math.exp(-(e.deltaMode ? e.deltaY * 33 : e.deltaY) * .0015), false);
  }
}, { passive: false });
cont.ondblclick = () => { if (medio?.tagName === "IMG") zoom(z > 1.02 ? 1 : 1.5); };
const dedos = new Map(); let d0 = 0, z0 = 1, mano = null;   // fotos: arrastrar para mover, pellizcar para acercar
cont.addEventListener("pointerdown", e => {
  if (medio?.tagName !== "IMG") return;
  dedos.set(e.pointerId, [e.clientX, e.clientY]);
  if (dedos.size === 2) { const [a, b] = [...dedos.values()]; d0 = Math.hypot(a[0] - b[0], a[1] - b[1]); z0 = z; mano = null; }
  else mano = [e.clientX, e.clientY, cont.scrollLeft, cont.scrollTop];
});
addEventListener("pointermove", e => {
  if (!dedos.has(e.pointerId)) return;
  dedos.set(e.pointerId, [e.clientX, e.clientY]);
  if (dedos.size === 2) { const [a, b] = [...dedos.values()]; zoom(z0 * Math.hypot(a[0] - b[0], a[1] - b[1]) / d0, false); }
  else if (mano) { cont.scrollLeft = mano[2] - e.clientX + mano[0]; cont.scrollTop = mano[3] - e.clientY + mano[1]; }
});
const soltar = e => { dedos.delete(e.pointerId); mano = null; };
addEventListener("pointerup", soltar); addEventListener("pointercancel", soltar);
addEventListener("resize", ajustar);
$$("#fotos, #videos").forEach(s => s.onclick = e => { const f = e.target.closest("figure"); if (!f || f.classList.contains("roto")) return; items = $$("figure:not(.roto)", s); verItem(items.indexOf(f)); });
$("#pdfs").onclick = e => { const b = e.target.closest("[data-pdf]"); if (b) verPdf(b.dataset.pdf, b.closest(".card").querySelector("h3").textContent); };
$("#ant").onclick = () => verItem(pos - 1);
$("#sig").onclick = () => verItem(pos + 1);
$("#visorX").onclick = cerrar;
$("#visorFs").onclick = () => document.fullscreenElement ? document.exitFullscreen() : visor.requestFullscreen?.();
addEventListener("keydown", e => {
  if (visor.hidden) return;
  if (e.key === "Escape") cerrar();
  if (e.key === "+" || e.key === "=") { e.preventDefault(); escalon(1); }
  if (e.key === "-") { e.preventDefault(); escalon(-1); }
  if (e.key === "0") { e.preventDefault(); zoom(1); }
  if (e.target.tagName === "VIDEO" || e.target.tagName === "INPUT" || $("#ant").hidden) return;
  if (e.key === "ArrowLeft") verItem(pos - 1);
  if (e.key === "ArrowRight") verItem(pos + 1);
});

/* ---------- Aviso claro si una foto o un video no se encuentra ---------- */
function marcarRoto(m) {
  const f = m.closest("#fotos figure, #videos figure");
  if (!f || f.classList.contains("roto")) return;
  f.classList.add("roto");
  const p = document.createElement("p"); p.className = "roto-msg";
  p.textContent = `No se pudo cargar: ${m.getAttribute("src")}. Revisa que el archivo esté dentro de la carpeta de la web (fotos/ o videos/), que la ruta en index.html sea correcta y que el formato sea compatible (videos: MP4 con H.264).`;
  f.prepend(p);
}
document.addEventListener("error", e => { if (e.target.matches?.("img, video")) marcarRoto(e.target); }, true);
$$("#fotos img, #videos video").forEach(m => { if ((m.tagName === "IMG" && m.complete && !m.naturalWidth && m.getAttribute("src")) || m.error) marcarRoto(m); });

/* ---------- Avisos pequeños (abajo en la pantalla) ---------- */
function toast(texto, url) {
  $$(".aviso-fondo").forEach(n => n.remove());
  const m = document.createElement("div"); m.className = "aviso-fondo"; m.textContent = texto + " ";
  if (url) {
    const l = document.createElement("a");
    Object.assign(l, { href: url, target: "_blank", rel: "noopener", textContent: "Abrir el archivo" });
    l.style.cssText = "color:var(--rojo2);font-weight:600"; m.append(l);
  }
  document.body.append(m); setTimeout(() => m.remove(), 15000);
}

/* ---------- Avisos, botón "Abrir aparte" y descargas ---------- */
function avisar(t, ms = 9000) {
  const m = document.createElement("div"); m.className = "aviso-fondo"; m.textContent = t;
  document.body.append(m); setTimeout(() => m.remove(), ms);
}
const abrir = document.createElement("a");   // plan B para guardar: abre el archivo en otra pestaña
Object.assign(abrir, { id: "visorAbrir", target: "_blank", rel: "noopener", textContent: "Abrir aparte" });
dl.before(abrir);
const nombreDe = u => { try { return decodeURIComponent(new URL(u, location.href).pathname.split("/").pop()) || "archivo"; } catch { return "archivo"; } };
document.addEventListener("click", async e => {
  const a = e.target.closest("a[download]:not([data-interno])");   // los enlaces que crea el propio código se ignoran
  if (!a || !a.getAttribute("href") || a.dataset.ocupado) return;
  e.preventDefault();
  const url = a.href, nombre = nombreDe(url), txt = a.textContent;
  if (location.protocol === "file:") {   // web abierta con doble clic: el navegador bloquea las descargas directas
    window.open(url, "_blank", "noopener");
    return avisar("Con doble clic el navegador no permite descargar directo. Se abrió el archivo en otra pestaña: clic derecho → Guardar como (en videos, menú ⋮ → Descargar). Con Live Server o en un hosting se descarga directo.", 15000);
  }
  a.dataset.ocupado = "1"; a.textContent = "Descargando…";
  try {
    const r = await fetch(url);
    if (!r.ok) throw new Error(r.status);
    const b = document.createElement("a");
    b.dataset.interno = "1"; b.href = URL.createObjectURL(await r.blob()); b.download = nombre;
    document.body.append(b); b.click(); b.remove();
    setTimeout(() => URL.revokeObjectURL(b.href), 60000);
  } catch {
    window.open(url, "_blank", "noopener");
    avisar("No se pudo guardar directamente. Se abrió el archivo en otra pestaña: clic derecho → Guardar como.");
  }
  a.textContent = txt; delete a.dataset.ocupado;
});

/* ---------- Video que se oye pero no se ve (formato no compatible, p. ej. H.265/HEVC) ---------- */
const MSG_VIDEO = "Este video se oye pero no se ve: tu navegador no puede mostrar su formato (suele ser H.265/HEVC del celular). Conviértelo a MP4 con H.264, por ejemplo con HandBrake.";
function revisarVideo(v) {
  if (v.readyState < 1 || v.videoWidth) return;
  const f = v.closest("figure");
  if (!f || f.classList.contains("sinimagen")) return;
  f.classList.add("sinimagen");
  const p = document.createElement("p"); p.className = "roto-msg"; p.textContent = MSG_VIDEO; f.prepend(p);
}
$$("#videos video").forEach(v => { v.addEventListener("loadedmetadata", () => revisarVideo(v)); revisarVideo(v); });

/* ---------- Panel cuando un video se oye pero no se ve ---------- */
function panelVideo() {
  const p = document.createElement("div"), t = document.createElement("b"), x = document.createElement("p");
  p.className = "video-aviso"; t.textContent = "El video se oye pero no se ve";
  x.textContent = "Tu navegador no puede mostrar la imagen de este formato (suele ser H.265/HEVC, de videos grabados con el celular). Conviértelo a MP4 con H.264 (por ejemplo con HandBrake) y vuelve a subirlo. Mientras tanto puedes descargarlo y verlo con el reproductor de tu computador.";
  p.append(t, x); visor.append(p);
}

/* ---------- Nombre del archivo en cada foto, video, audio y PDF ---------- */
$$("#fotos figure, #videos figure").forEach(f => {
  const m = f.querySelector("img, video"), c = f.querySelector("figcaption");
  if (m && c) c.append(Object.assign(document.createElement("small"), { className: "nombre", textContent: nombreDe(m.getAttribute("src").split("#")[0]) }));
});
$$("#audios .card, #pdfs .card").forEach(c => {
  const m = c.querySelector("audio, [data-pdf]"), h = c.querySelector("h3"), r = m && (m.getAttribute("src") || m.dataset.pdf);
  if (r && h) h.after(Object.assign(document.createElement("small"), { className: "nombre", textContent: nombreDe(r) }));
});

/* ---------- Un solo audio/video sonando a la vez ---------- */
document.addEventListener("play", e => $$("audio,video").forEach(m => m !== e.target && m.pause()), true);

/* ---------- Libro de historia ----------
   Tus páginas del libro ahora están escritas a mano en index.html (tarjetas dentro de #paginas).
   Este bloque solo se usa si existe el formulario del libro (#formLibro). Si no existe, se salta:
   antes daba error aquí y se detenía TODO lo de abajo (menú por secciones y corazones). */
if ($("#formLibro")) {
  const KEY = "libro-angelo-maribel"; let libro = [];
  try { libro = JSON.parse(localStorage.getItem(KEY)) || []; } catch {}
  $("#fecha").valueAsDate = new Date();
  function pintar() {
    const l = $("#paginas"); l.innerHTML = "";
    libro.sort((a, b) => b.f.localeCompare(a.f)).forEach((h, i) => {
      const a = document.createElement("article"), t = document.createElement("time"), p = document.createElement("p"), x = document.createElement("button");
      a.className = "pagina";
      t.textContent = new Date(h.f + "T12:00").toLocaleDateString("es", { day: "numeric", month: "long", year: "numeric" });
      p.textContent = h.t; x.textContent = "Borrar";
      x.onclick = () => { if (confirm("¿Borrar esta página?")) { libro.splice(i, 1); guardar(); } };
      a.append(t, p, x); l.append(a);
    });
  }
  function guardar() { try { localStorage.setItem(KEY, JSON.stringify(libro)); } catch {} pintar(); }
  $("#formLibro").onsubmit = e => { e.preventDefault(); libro.push({ f: $("#fecha").value, t: $("#texto").value.trim() }); $("#texto").value = ""; guardar(); };
  pintar();
}

/* ---------- Menú: cada apartado es una pantalla aparte (solo se cambia desde el menú) ---------- */
const enlaces = $$("nav a[href^='#']"), vistas = $$(".vista");
function mostrar(id) {
  vistas.forEach(v => v.hidden = v.id !== id);
  enlaces.forEach(a => { const on = a.getAttribute("href") === "#" + id; a.classList.toggle("activo", on); a.setAttribute("aria-current", on ? "true" : "false"); });
  scrollTo(0, 0);
}
enlaces.forEach(a => a.onclick = e => { e.preventDefault(); mostrar(a.getAttribute("href").slice(1)); });
mostrar("inicio");

/* ---------- Fondo animado: corazones rojos flotando ---------- */
const cv = $("#fondo"), cx = cv.getContext("2d"); let W, H;
const medir = () => { W = cv.width = innerWidth; H = cv.height = innerHeight; };
medir(); addEventListener("resize", medir);
const ps = Array.from({ length: 50 }, () => ({ x: Math.random() * W, y: Math.random() * H, s: 8 + Math.random() * 22, v: .25 + Math.random() * .8, a: Math.random() * 6.28, o: .1 + Math.random() * .4 }));
(function anim() {
  cx.clearRect(0, 0, W, H);
  ps.forEach(p => {
    p.y -= p.v; p.a += .015;
    if (p.y < -30) { p.y = H + 30; p.x = Math.random() * W; }
    cx.globalAlpha = p.o; cx.fillStyle = "#e0162b"; cx.font = p.s + "px serif";
    cx.fillText("♥", p.x + Math.sin(p.a) * 22, p.y);
  });
  requestAnimationFrame(anim);
})();

/* ---------- Imagen de fondo de respaldo ----------
   Si la imagen que pones en index.html no se encuentra, se usa esta y aparece un aviso.
   NO borres la línea larga de abajo. */
const FONDO_RESPALDO = "data:image/jpeg;base64,";
const fondoImg = $("#fondoImg");
function usarRespaldo() {
  if (fondoImg.dataset.respaldo) return;
  const mala = fondoImg.getAttribute("src");
  fondoImg.dataset.respaldo = "1"; fondoImg.src = FONDO_RESPALDO;
  const m = document.createElement("div"); m.className = "aviso-fondo";
  m.textContent = `No se encontró la imagen de fondo "${mala}". Revisa el nombre y que esté en la misma carpeta que index.html.`;
  document.body.append(m); setTimeout(() => m.remove(), 12000);
}
fondoImg.addEventListener("error", usarRespaldo);
if (fondoImg.complete && !fondoImg.naturalWidth) usarRespaldo();

